  def('signpost', function (g, rw, rh) { var p = ctr(g, rw, rh); g.line([p[0], p[1]], [p[0], p[1] - 32], '#7A4B2A', 2.4); [[-10, -28, '#4F80BA'], [10, -22, '#2E9E7F'], [-8, -16, '#F2802B']].forEach(function (q) { g.poly([[p[0], p[1] + q[1] - 3], [p[0] + q[0], p[1] + q[1] - 3], [p[0] + q[0] * 1.15, p[1] + q[1]], [p[0] + q[0], p[1] + q[1] + 3], [p[0], p[1] + q[1] + 3]], q[2], INK); }); });
