  function lampPole(g, p, h, col) { g.line([p[0], p[1]], [p[0], p[1] - h], col || '#4B4F5A', 2.2); }
  def('streetlamp', function (g, rw, rh) { var p = ctr(g, rw, rh); shadow(g, p, 5); lampPole(g, p, 28); g.line([p[0], p[1] - 28], [p[0] + 6, p[1] - 30], '#4B4F5A', 2); g.ell(p[0] + 7, p[1] - 29, 4, 2.6, '#FFE9A0', INK); g.glow.push({ c: [p[0] + 7, p[1] - 29], r: 16 }); });
  def('classiclamp', function (g, rw, rh) { var p = ctr(g, rw, rh); shadow(g, p, 6); g.box(.4, .4, .2, .2, 0, 5, '#2E3340'); lampPole(g, [p[0], p[1] - 5], 24, '#2E3340'); g.poly([[p[0] - 5, p[1] - 29], [p[0] + 5, p[1] - 29], [p[0] + 4, p[1] - 40], [p[0] - 4, p[1] - 40]], '#FFE9A0', INK); g.poly([[p[0] - 6, p[1] - 40], [p[0] + 6, p[1] - 40], [p[0], p[1] - 46]], '#2E3340', false); g.glow.push({ c: [p[0], p[1] - 34], r: 15 }); });
  def('modernlamp', function (g, rw, rh) { var p = ctr(g, rw, rh); shadow(g, p, 5); lampPole(g, p, 34, '#9AA6B4'); g.poly([[p[0] - 10, p[1] - 36], [p[0] + 10, p[1] - 36], [p[0] + 8, p[1] - 33], [p[0] - 8, p[1] - 33]], '#E6F3FF', INK); g.glow.push({ c: [p[0], p[1] - 34], r: 18 }); });
  def('gardenlamp', function (g, rw, rh) { var p = ctr(g, rw, rh); lampPole(g, p, 12, '#4B4F5A'); g.ell(p[0], p[1] - 14, 4.4, 4.4, '#FFF3B0', INK); g.glow.push({ c: [p[0], p[1] - 14], r: 11 }); });
  def('stonelantern', function (g, rw, rh) { var p = ctr(g, rw, rh); shadow(g, p, 7); g.box(.36, .36, .28, .28, 0, 5, '#B8B2A4'); g.box(.42, .42, .16, .16, 5, 11, '#C9C4B8'); g.box(.35, .35, .3, .3, 11, 19, '#D6D0C2'); g.quadL(.35, .35, .3, .3, .3, .7, 12, 18, '#FFE08A'); g.hip(.3, .3, .4, .4, 19, 26, '#9C968A', .2); g.glow.push({ c: g.P(.5, .65, 15), r: 10 }); });
  def('pathlight', function (g, rw, rh) { var p = ctr(g, rw, rh); g.box(.42, .42, .16, .16, 0, 9, '#4B4F5A'); g.ell(p[0], p[1] - 10, 3.4, 2, '#FFF3B0'); g.glow.push({ c: [p[0], p[1] - 10], r: 9 }); });
  def('fairytree', function (g, rw, rh) { var p = ctr(g, rw, rh); shadow(g, p, 10); trunk(g, p, 1.1); canopy(g, p, 1.1, ['#2E8A4F', '#3FA55B']); var i; for (i = 0; i < 14; i++) { var a = i * 2.4, r = 5 + (i % 4) * 2.2, x = p[0] + Math.cos(a) * r * 1.1, y = p[1] - 17 + Math.sin(a) * r * .8; dot(g, x, y, 1.5, ['#FFE08A', '#FF9AC0', '#9FD8F5', '#fff'][i % 4]); g.glow.push({ c: [x, y], r: 5 }); } });
  def('neonsign', function (g) { g.box(.44, .44, .12, .12, 0, 18, '#4B4F5A'); g.quadL(.2, .4, .6, .2, 0, 1, 16, 34, '#241A3A', INK); g.quadL(.2, .4, .6, .2, .1, .9, 19, 31, '#2A2150'); g.quadL(.2, .4, .6, .2, .16, .84, 24, 26, '#FF4FD8'); g.quadL(.2, .4, .6, .2, .16, .84, 20, 22, '#2FE6F2'); g.glow.push({ c: g.P(.5, .8, 26), r: 15 }); });
  def('torch', function (g, rw, rh) { var p = ctr(g, rw, rh); lampPole(g, p, 22, '#6B4A2E'); g.poly([[p[0] - 3.4, p[1] - 22], [p[0] + 3.4, p[1] - 22], [p[0] + 2.4, p[1] - 27], [p[0] - 2.4, p[1] - 27]], '#4B4F5A', false); g.poly([[p[0] - 3, p[1] - 27], [p[0], p[1] - 37], [p[0] + 3, p[1] - 27]], '#FF9A2E', false); g.poly([[p[0] - 1.6, p[1] - 27], [p[0], p[1] - 33], [p[0] + 1.6, p[1] - 27]], '#FFE08A', false); g.glow.push({ c: [p[0], p[1] - 30], r: 14 }); });
  def('lanternstring', function (g) { var a = g.P(.1, .5, 0), b = g.P(.9, .5, 0); g.line(a, [a[0], a[1] - 30], '#7A4B2A', 2.4); g.line(b, [b[0], b[1] - 30], '#7A4B2A', 2.4); g.c.strokeStyle = '#3A3A3A'; g.c.lineWidth = 1.2; g.c.beginPath(); g.c.moveTo(a[0], a[1] - 30); g.c.quadraticCurveTo((a[0] + b[0]) / 2, a[1] - 18, b[0], b[1] - 30); g.c.stroke(); var i; for (i = 1; i <= 4; i++) { var t = i / 5, x = a[0] + (b[0] - a[0]) * t, y = (a[1] - 30) * (1 - t) * (1 - t) + 2 * (1 - t) * t * (a[1] - 18) + (b[1] - 30) * t * t; g.ell(x, y + 5, 3.4, 4.2, ['#E9573F', '#FFD84A', '#FF7AA8', '#6FD0FF'][i % 4], INK); g.glow.push({ c: [x, y + 5], r: 8 }); } });
  def('solarlamp', function (g, rw, rh) { var p = ctr(g, rw, rh); shadow(g, p, 5); lampPole(g, p, 32, '#8A94A4'); g.poly([[p[0] - 8, p[1] - 38], [p[0] + 8, p[1] - 41], [p[0] + 8, p[1] - 36], [p[0] - 8, p[1] - 33]], '#2F4E8A', INK); g.line([p[0] - 4, p[1] - 36], [p[0] - 4, p[1] - 40], '#7FB4E8', 1); g.ell(p[0], p[1] - 31, 3, 2, '#FFF3B0'); g.glow.push({ c: [p[0], p[1] - 31], r: 12 }); });
