  def('grandfountain', function (g, rw, rh) { var c = ctr(g, rw, rh); g.poly(g.faceT(.1, .1, rw - .2, rh - .2, 0), '#D8D2C2', INK); g.ell(c[0], c[1], 26, 13, '#C9C4B8', INK); g.ell(c[0], c[1] + 1, 22, 10.6, '#62C3EA'); g.cyl(rw / 2, rh / 2, .2, 0, 14, '#C9C4B8'); g.ell(c[0], c[1] - 20, 10, 4.6, '#C9C4B8', INK); g.ell(c[0], c[1] - 20, 7, 3, '#62C3EA'); g.meta.water.push([c[0], c[1] - 24]); g.meta.water.push([c[0] - 14, c[1] - 2]); g.meta.water.push([c[0] + 14, c[1] - 2]); });
