  def('angel', function (g, rw, rh) { var p = ctr(g, rw, rh); shadow(g, p, 9); g.box(.32, .32, .36, .36, 0, 10, '#D6D0C2'); var t = g.P(.5, .5, 10); g.poly([[t[0] - 4, t[1]], [t[0] + 4, t[1]], [t[0] + 2.6, t[1] - 20], [t[0] - 2.6, t[1] - 20]], '#F4F2EA', INK); g.ell(t[0], t[1] - 23, 3.4, 3.8, '#F4F2EA', INK); g.poly([[t[0] - 2, t[1] - 17], [t[0] - 15, t[1] - 24], [t[0] - 11, t[1] - 10]], '#fff', INK); g.poly([[t[0] + 2, t[1] - 17], [t[0] + 15, t[1] - 24], [t[0] + 11, t[1] - 10]], '#fff', INK); g.ell(t[0], t[1] - 28, 4, 1.2, '#FFE08A'); });
  def('rockgarden', function (g) { g.poly(g.faceT(.08, .08, .84, .84, 0), '#E4DCC8', INK); var i; for (i = 0; i < 4; i++) g.line(g.P(.16, .22 + i * .18, 0), g.P(.84, .22 + i * .18, 0), 'rgba(120,110,90,.35)', 1); [[.3, .4, 7], [.62, .56, 9], [.46, .72, 5]].forEach(function (q) { var p = g.P(q[0], q[1], 0); g.ell(p[0], p[1] - q[2] * .4, q[2], q[2] * .7, '#9AA3AE', INK); g.ell(p[0] - 1, p[1] - q[2] * .6, q[2] * .5, q[2] * .3, 'rgba(255,255,255,.3)'); }); });
  def('zengarden', function (g) { g.poly(g.faceT(.05, .05, .9, .9, 0), '#EFE8D6', INK); var i; for (i = 0; i < 6; i++) g.line(g.P(.14, .2 + i * .12, 0), g.P(.86, .2 + i * .12, 0), 'rgba(140,128,100,.4)', 1.2); [[.3, .5, 6], [.58, .4, 8], [.7, .66, 5]].forEach(function (q) { var p = g.P(q[0], q[1], 0); g.ell(p[0], p[1] - q[2] * .4, q[2], q[2] * .65, '#7C8590', INK); }); var t = g.P(.8, .22, 0); g.line(t, [t[0], t[1] - 14], '#7A5A3A', 2); g.ell(t[0], t[1] - 17, 5, 4, '#3FA55B', INK); });
  def('koipond', function (g, rw, rh) { var c = ctr(g, rw, rh); g.poly(g.faceT(.08, .08, rw - .16, rh - .16, 0), '#B8B2A4', INK); g.ell(c[0], c[1], 24, 11.6, '#9AA3AE', INK); g.ell(c[0], c[1] + 1, 21, 9.6, '#4DB1EA'); g.ell(c[0] - 6, c[1] - 1, 7, 3, '#3FA55B'); g.ell(c[0] + 8, c[1] + 2, 5, 2.4, '#3FA55B'); dot(g, c[0] - 6, c[1] - 3, 2, '#FF9AC0'); g.meta.duck.push([c[0] + 3, c[1] + 1]); g.meta.duck.push([c[0] - 8, c[1] + 3]); });
