  def('gazebo', function (g, rw, rh) { var c = ctr(g, rw, rh); g.poly(g.faceT(.12, .12, rw - .24, rh - .24, 0), '#D8D2C2', INK); [[.3, .3], [rw - .3, .3], [.3, rh - .3], [rw - .3, rh - .3]].forEach(function (q) { var a = g.P(q[0], q[1], 0); g.line(a, [a[0], a[1] - 34], '#F2F0E6', 3); }); g.hip(.15, .15, rw - .3, rh - .3, 34, 50, '#C9674A', .08); g.box(.4, .4, .2, .2, 0, 4, '#B8844E'); });
  def('pergola', function (g, rw, rh) { var a = g.P(.1, .5, 0), b = g.P(rw - .1, .5, 0), i; for (i = 0; i < 3; i++) { var t = i / 2, x = a[0] + (b[0] - a[0]) * t, y = a[1] + (b[1] - a[1]) * t; g.line([x, y], [x, y - 28], '#B8956A', 3); g.line([x - 8, y - 28 + 2], [x + 8, y - 28 - 2], '#B8956A', 2.4); dot(g, x, y - 29, 3, ['#FF7AA8', '#B48CFF', '#fff'][i]); g.ell(x + 3, y - 26, 3, 1.4, '#3E9E4B'); } g.line([a[0], a[1] - 28], [b[0], b[1] - 28], '#B8956A', 3); });
  def('minimill', function (g, rw, rh) { var p = ctr(g, rw, rh); shadow(g, p, 8); g.poly([[p[0] - 7, p[1]], [p[0] + 7, p[1]], [p[0] + 4, p[1] - 22], [p[0] - 4, p[1] - 22]], '#F4EAD6', INK); g.poly([[p[0] - 5, p[1] - 22], [p[0] + 5, p[1] - 22], [p[0], p[1] - 29]], '#C9674A', INK); rotAt(g, p[0], p[1] - 20, 'blades', 15, 0); g.ext(p[0], p[1] - 36, 16); });
