  def('sundial', function (g, rw, rh) { var p = ctr(g, rw, rh); g.cyl(.5, .5, .3, 0, 9, '#C9C4B8', '#E4DED2'); var t = g.P(.5, .5, 9); g.poly([[t[0], t[1]], [t[0] + 7, t[1] - 8], [t[0] + 1, t[1] - 1]], '#8A5A33', false); for (var i = 0; i < 6; i++) { var a = -.6 + i * .36; g.line([t[0] + Math.cos(a) * 8, t[1] + Math.sin(a) * 4], [t[0] + Math.cos(a) * 10, t[1] + Math.sin(a) * 5], '#6B6256', 1); } });
  def('obelisk', function (g, rw, rh) { var p = ctr(g, rw, rh); shadow(g, p, 8); g.box(.3, .3, .4, .4, 0, 5, '#9C968A'); var b1 = g.P(.36, .64, 5), b2 = g.P(.64, .64, 5), b3 = g.P(.64, .36, 5), t = g.P(.5, .5, 46); g.poly([b1, b2, t], '#B8B2A4', INK); g.poly([b2, b3, t], '#D6D0C2', INK); g.line(b2, t, 'rgba(0,0,0,.2)', 1); });
  def('gardenarch', function (g) { var a = g.P(.14, .5, 0), b = g.P(.86, .5, 0); g.line(a, [a[0], a[1] - 26], '#F2F0E6', 4); g.line(b, [b[0], b[1] - 26], '#F2F0E6', 4); g.c.strokeStyle = '#F2F0E6'; g.c.lineWidth = 4; g.c.beginPath(); g.c.moveTo(a[0], a[1] - 26); g.c.quadraticCurveTo((a[0] + b[0]) / 2, a[1] - 50, b[0], b[1] - 26); g.c.stroke(); g.ext((a[0] + b[0]) / 2, a[1] - 42, 8); dot(g, (a[0] + b[0]) / 2, a[1] - 38, 2.4, '#FFD84A'); });
  def('scarecrow', function (g, rw, rh) { var p = ctr(g, rw, rh); g.line([p[0], p[1]], [p[0], p[1] - 28], '#7A4B2A', 2.4); g.line([p[0] - 11, p[1] - 20], [p[0] + 11, p[1] - 20], '#7A4B2A', 2.4); g.poly([[p[0] - 6, p[1] - 22], [p[0] + 6, p[1] - 22], [p[0] + 4, p[1] - 10], [p[0] - 4, p[1] - 10]], '#4F80BA', INK); g.ell(p[0], p[1] - 27, 4.4, 4.4, '#F4D98A', INK); g.poly([[p[0] - 7, p[1] - 29], [p[0] + 7, p[1] - 29], [p[0] + 3, p[1] - 36], [p[0] - 3, p[1] - 36]], '#8C5A44', INK); g.line([p[0] - 11, p[1] - 20], [p[0] - 14, p[1] - 14], '#E4B84A', 1.4); g.line([p[0] + 11, p[1] - 20], [p[0] + 14, p[1] - 14], '#E4B84A', 1.4); });
