  function crops(g, rw, rh, col, top) { g.poly(g.faceT(.04, .04, rw - .08, rh - .08, 0), '#8C6B4F', INK); var i, j; for (j = 0; j < Math.floor(rh * 3); j++) { var a = g.P(.14, .12 + j * .33, 0), b = g.P(rw - .14, .12 + j * .33, 0); g.line([a[0], a[1] - 1], [b[0], b[1] - 1], shade('#8C6B4F', .72), 3); for (i = 0; i < Math.floor(rw * 4); i++) { var t = (i + .5) / (rw * 4), q = [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t - 2]; dot(g, q[0], q[1] - 1.5, 1.9, i % 2 ? col : shade(col, .86)); if (top) dot(g, q[0], q[1] - 3.6, 1.1, top); } } }
