  def('pasture', function (g, rw, rh) { g.poly(g.faceT(0, 0, rw, rh, 0), '#A8E070', INK); g.poly(g.faceT(.1, .1, rw - .2, rh - .2, 1), '#B8E87E', '#B8844E', 1.8); [[.8, .8, 0], [1.7, 1.2, 1], [1.2, 2.0, 0], [2.2, 2.2, 1]].forEach(function (q) { var p = g.P(q[0], q[1], 1); g.ell(p[0], p[1] - 4, 6.4, 4, q[2] ? '#6B4A2E' : '#fff', INK); if (!q[2]) { dot(g, p[0] - 2, p[1] - 5, 1.6, '#222'); dot(g, p[0] + 2, p[1] - 3, 1.4, '#222'); } g.ell(p[0] + 6, p[1] - 6, 2.8, 2.6, q[2] ? '#6B4A2E' : '#fff', INK); g.line([p[0] - 4, p[1]], [p[0] - 4, p[1] + 3], '#4B4F5A', 1.4); g.line([p[0] + 3, p[1]], [p[0] + 3, p[1] + 3], '#4B4F5A', 1.4); }); g.tree(.3, .3, .8); g.tree(2.7, 2.7, .8); });
